// Sanitize and Validate Lead Data
const body = $input.first().json.body || $input.first().json;

const customerName = (body.customerName || '').trim();
let phone = (body.phone || '').trim().replace(/[\s\-\(\)]/g, '');

if (!customerName) {
  throw new Error('Customer Name is required');
}

if (!phone || phone.length < 8) {
  throw new Error('Valid Phone Number is required');
}

// Format E.164
if (!phone.startsWith('+')) {
  phone = '+' + (phone.length === 10 ? '1' + phone : phone);
}

return [{
  json: {
    leadId: 'LEAD-' + Date.now().toString().slice(-6),
    createdAt: new Date().toISOString(),
    customerName,
    phone,
    email: body.email || '',
    socialMediaSource: body.socialMediaSource || 'instagram',
    campaign: body.campaign || 'reels_organic',
    productId: body.productId || 'PROD-CLOTH-001',
    productName: body.productName || 'Featured Collection Item',
    initialEnquiry: body.initialEnquiry || 'Interested from Instagram Reel',
    leadStatus: 'New Lead',
    leadScore: 'Warm'
  }
}];

