// Parse Gemini Output & Compute Lead Score
const response = $input.first().json;
let rawText = '';
try {
  rawText = response.candidates[0].content.parts[0].text;
} catch(e) {
  rawText = '{}';
}

const cleaned = rawText.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = { purchaseIntent: 'INTERESTED_EXPLORING', customerSentiment: 'POSITIVE', summary: 'Call completed' };
}

// Compute Numerical Score
let score = 50;
if (parsed.purchaseIntent === 'STRONG_BUY' || parsed.orderPlaced) score += 40;
else if (parsed.purchaseIntent === 'INTERESTED_EXPLORING') score += 15;
else if (parsed.purchaseIntent === 'PRICE_SENSITIVE') score += 5;
else if (parsed.purchaseIntent === 'NOT_INTERESTED') score -= 30;

if (parsed.customerSentiment === 'VERY_POSITIVE') score += 15;
else if (parsed.customerSentiment === 'NEGATIVE') score -= 20;

score = Math.max(10, Math.min(100, score));

let leadScore = 'Warm';
if (score >= 80) leadScore = 'Hot';
else if (score < 40) leadScore = 'Cold';

return [{
  json: {
    ...parsed,
    leadScore,
    scoreNumerical: score,
    conversationId: $('6. Post-Call Transcript Webhook').first().json.conversationId || 'CONV-' + Date.now(),
    leadId: $('6. Post-Call Transcript Webhook').first().json.leadId || 'N/A'
  }
}];

